        "localizador": "L02"
      }
    ],
    "lacunas": [],
    "motivo": "Término da linha base declarado como D12.",
    "unidade": "dia_corrido"
  },
  "fim_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_f7ff82",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "A ficha d_a70f, indicada como fonte de todas as precedências, não está disponível; não é possível determinar se a redução de duração altera o término final."
    ],
    "motivo": "O aviso reduz a duração do dossiê, mas os dados visíveis não permitem determinar o efeito no término do projeto.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_f7ff82",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "Faltam as precedências da ficha d_a70f; não se sabe se o término fica inalterado ou antecipa, nem a magnitude da variação."
    ],
    "motivo": "Não é possível comparar quantitativamente o novo término ao D12 da linha base sem as precedências.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      }
    ],
    "lacunas": [],
    "motivo": "Custo da linha base declarado como R$ 1.650,00 e discriminado nas obrigações.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_f7ff82",
        "localizador": "L01"
      }
    ],
    "lacunas": [],
    "motivo": "As seis parcelas fixas totalizam R$ 1.000,00; o apoio contratado permanece em R$ 650,00 em caso de antecipação pela política sem crédito; o aviso não tem custo direto.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "exato",
    "valor": 0,
    "direcao": "zero",
    "evidencias": [
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_f7ff82",
        "localizador": "L01"
      }
    ],
    "lacunas": [],
    "motivo": "As obrigações fixas não variam com o prazo; o apoio não gera crédito por antecipação e o aviso não acrescenta custo direto.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "A redução de dois dias na duração de Emitir dossiê não permite quantificar a alteração do término sem as precedências da ficha d_a70f. O custo permanece em R$ 1.650,00: as parcelas fixas não variam com o prazo, a política do apoio não concede crédito por antecipação e o aviso não tem custo direto."
}

